"""Every rounding rule of meterbill lives here (see docs/rounding.md)."""

from __future__ import annotations

import math
from decimal import Decimal, InvalidOperation
from fractions import Fraction

CENT = Decimal("0.01")
HALF_UP = "half_up"
HALF_EVEN = "half_even"
DOWN = "down"

_METHODS = (HALF_UP, HALF_EVEN, DOWN)


def _check(step, method) -> None:
    if method not in _METHODS:
        raise ValueError(f"unknown rounding method: {method!r}")
    if not step.is_finite() or step <= 0:
        raise ValueError("step must be positive")


def _round_fraction(q: Fraction, negative: bool, step: Decimal, method: str) -> Decimal:
    """`q` (an exact value) to a multiple of `step`, exactly, whatever its size."""
    multiples = abs(q) / Fraction(step)
    whole = multiples.numerator // multiples.denominator
    twice = 2 * (multiples - whole)
    if method == HALF_UP:
        up = twice >= 1
    elif method == HALF_EVEN:
        up = twice > 1 or (twice == 1 and whole % 2 == 1)
    else:
        up = False
    n = whole + 1 if up else whole
    _, _, exponent = step.as_tuple()
    coefficient = n * int(step.scaleb(-exponent))
    digits = tuple(int(c) for c in str(coefficient))
    return Decimal((1 if negative else 0, digits, exponent))


def round_amount(value: Decimal, step: Decimal, method: str) -> Decimal:
    if not isinstance(value, Decimal) or not isinstance(step, Decimal):
        raise TypeError("value and step must be Decimal")
    _check(step, method)
    if value.is_nan():
        return value
    if value.is_infinite():
        raise InvalidOperation("cannot round an infinite value")
    return _round_fraction(Fraction(value), value.is_signed(), step, method)


def allocate(amounts: list[Decimal], step: Decimal) -> list[Decimal]:
    """One part per amount, cut down to `step`; the difference against the
    rounded total goes on the last amount that is not zero."""
    parts = [round_amount(a, step, DOWN) for a in amounts]
    exact = sum((Fraction(a) for a in amounts), Fraction(0))
    whole = _round_fraction(exact, exact < 0, step, HALF_UP)
    _, _, exponent = step.as_tuple()
    zero = Decimal((0, (0,), exponent))
    rest = whole - _exact_sum(parts, zero)
    for i in range(len(parts) - 1, -1, -1):
        if amounts[i] != 0:
            parts[i] = _exact_sum([parts[i], rest], zero)
            break
    return parts


def _exact_sum(values: list, start: Decimal) -> Decimal:
    """Sum of decimals without the precision limit of decimal arithmetic."""
    exponent = min([start.as_tuple().exponent] + [v.as_tuple().exponent for v in values])
    total = Fraction(start)
    for v in values:
        total += Fraction(v)
    n = int(total / Fraction(Decimal((0, (1,), exponent))))
    return Decimal((1 if n < 0 else 0, tuple(int(c) for c in str(abs(n))), exponent))


def legacy_cents(value: float, places: int = 2) -> float:
    scale = 10 ** places
    return math.floor(value * scale + 0.5) / scale


def fixed(value: float | Decimal, places: int, method: str = HALF_EVEN) -> str:
    if isinstance(value, Decimal):
        if value.is_finite():
            step = Decimal((0, (1,), -places))
            return format(round_amount(value, step, method), "f")
        _check(CENT, method)
        return format(value, "f")
    if not isinstance(value, float):
        raise TypeError("value must be a float or a Decimal")
    if method != HALF_EVEN:
        raise ValueError(f"a float is only written half to even, not {method!r}")
    return format(value, f".{places}f")
EOF

